import { inject } from 'vue'
import { APP_CONFIG_KEY, type AppConfig } from '@@vyui:lib/types'
import icons from '@@vyui:theme/icons'

/**
 * Fallback config used when components are rendered outside a `VyUI` app
 * context (storybook, isolated tests). Keeps the icon registry intact so
 * `useComponentIcons` still resolves semantic names.
 */
const FALLBACK_CONFIG: AppConfig = {
  ui: {
    icons,
    primary: 'green',
    gray: 'slate',
  },
}

/** Inject the merged `AppConfig` provided by `VyUI.install()`. */
export const useAppConfig = (): AppConfig => inject(APP_CONFIG_KEY, FALLBACK_CONFIG)

import { computed, type ComputedRef, type MaybeRefOrGetter, toValue } from 'vue'
import { tv, type ClassValue, type TVReturnType, type VariantProps } from 'tailwind-variants'
import { resolveColors } from '@@vyui:theme/colors'
import { useAppConfig } from '@@vyui:composables/useAppConfig'

/** The factory returned by calling `tv(theme)`. */
export type TVFactory = ReturnType<typeof tv>

/** Unwraps a builder theme (`(colors) => themeObject`) to its config object. */
export type ResolveTheme<T> = T extends (...args: never[]) => infer R ? R : T

/**
 * Build a per-app-config `tv` factory for a styled component: merges the package
 * default theme with any user override at `appConfig.ui[name]` and returns the
 * invoked slot map (under `ui`).
 *
 * @param name      Key under `appConfig.ui` where user overrides live.
 * @param theme     The package default theme — a builder function (invoked with
 *                  the resolved color list) or a plain `tv` config object.
 * @param variants  Variant props; ref, getter, or plain object.
 */
export function useStyledComponent<TTheme>(
  name: string,
  theme: TTheme,
  variants: MaybeRefOrGetter<Record<string, unknown>>,
): {
  ui: ComputedRef<ReturnType<ThemeTV<TTheme>>>
} {
  const appConfig = useAppConfig()
  const tvFactory = computed(() => {
    // Factories are memoized on (appConfig, name): the config is stable per app
    // and not reactive, so per-instance rebuilds cost real time on PrimJS.
    let perApp = factoryCache.get(appConfig)
    if (!perApp) {
      perApp = new Map()
      factoryCache.set(appConfig, perApp)
    }
    const cached = perApp.get(name)
    if (cached)
      return cached

    const base = typeof theme === 'function'
      ? (theme as (colors: string[]) => unknown)(resolveColors(appConfig))
      : theme
    const overrides = (appConfig.ui as Record<string, unknown>)[name] as Record<string, unknown> | undefined
    // `extend: tv(base)` lets app-level overrides win key-by-key while still
    // inheriting the package default. Cast through `unknown` because `tv` is an
    // overloaded interface, not a generic function.
    const factory = tv({ extend: tv(base as never), ...(overrides || {}) } as never) as unknown as TVFactory
    perApp.set(name, factory)
    return factory
  })
  // The runtime factory is untyped (`TVFactory`); `ThemeTV<TTheme>` recovers
  // the theme's real slot keys for callers.
  const ui = computed(() => tvFactory.value(toValue(variants) as Parameters<TVFactory>[0])) as ComputedRef<ReturnType<ThemeTV<TTheme>>>
  return { ui }
}

/** Built `tv` factories per app config, keyed by component theme name. */
const factoryCache = new WeakMap<object, Map<string, TVFactory>>()

/**
 * The `tv` factory type for a theme. `tv` is an overloaded interface, so
 * `ReturnType<typeof tv<typeof theme>>` doesn't work — project the theme's
 * `slots` / `variants` into `TVReturnType` instead.
 */
export type ThemeTV<TTheme, R = ResolveTheme<TTheme>> = TVReturnType<
  R extends { variants: infer V } ? (V extends Record<string, any> ? V : any) : any,
  R extends { slots: infer S } ? (S extends Record<string, any> ? S : any) : any,
  // B (base) stays `any`; the rest must NOT be. `TVProps` branches on the
  // extend-variants param — `any` there widens every variant key to
  // `PropertyKey` and loses the literal `color` union.
  any, {}, {}, undefined, undefined
>

export type { ClassValue, VariantProps }

import { computed, toValue, type MaybeRefOrGetter } from 'vue'
import { useAppConfig } from '@@vyui:composables/useAppConfig'

// Ported from nuxt/ui v3.0.2 `src/runtime/composables/useComponentIcons.ts`. The
// `avatar` prop stays loosely typed to avoid depending on `Avatar`'s props.

export interface UseComponentIconsProps {
  /**
   * Display an icon based on the `leading` and `trailing` props.
   * @IconifyIcon
   */
  icon?: string
  /** Display an avatar on the left side. */
  avatar?: unknown
  /** When `true`, the icon will be displayed on the left side. */
  leading?: boolean
  /**
   * Display an icon on the left side.
   * @IconifyIcon
   */
  leadingIcon?: string
  /** When `true`, the icon will be displayed on the right side. */
  trailing?: boolean
  /**
   * Display an icon on the right side.
   * @IconifyIcon
   */
  trailingIcon?: string
  /** When `true`, the loading icon will be displayed. */
  loading?: boolean
  /**
   * The icon when the `loading` prop is `true`.
   * @defaultValue appConfig.ui.icons.loading
   * @IconifyIcon
   */
  loadingIcon?: string
}

export function useComponentIcons(componentProps: MaybeRefOrGetter<UseComponentIconsProps>) {
  const appConfig = useAppConfig()

  const props = computed(() => toValue(componentProps))

  const isLeading = computed(() => (props.value.icon && props.value.leading) || (props.value.icon && !props.value.trailing) || (props.value.loading && !props.value.trailing) || !!props.value.leadingIcon)
  const isTrailing = computed(() => (props.value.icon && props.value.trailing) || (props.value.loading && props.value.trailing) || !!props.value.trailingIcon)

  const leadingIconName = computed(() => {
    if (props.value.loading) {
      return props.value.loadingIcon || appConfig.ui.icons?.loading
    }

    return props.value.leadingIcon || props.value.icon
  })
  const trailingIconName = computed(() => {
    if (props.value.loading && !isLeading.value) {
      return props.value.loadingIcon || appConfig.ui.icons?.loading
    }

    return props.value.trailingIcon || props.value.icon
  })

  return {
    isLeading,
    isTrailing,
    leadingIconName,
    trailingIconName,
  }
}

// Explicit `.js` — `tailwindcss/colors` has no `exports` map, so the
// extensionless specifier resolves under bundlers but throws under Node's pure
// ESM resolver (which the packed-tarball smoke test uses). The `.js` form works
// everywhere.
import twColors from 'tailwindcss/colors.js'
import type { AppConfig } from '@@vyui:lib/types'
import { SEMANTIC_TO_PALETTE_DEFAULT } from '@@vyui:theme/color-constants'

const FALLBACK_HEX = '#64748b' // slate-500

/**
 * Resolve a semantic color (`primary`, `error`, …) plus shade to a literal hex
 * string, for coloring Lynx `<svg>` icons — Lynx rasterizes the XML and can't
 * inherit `currentColor`, so the fill is baked at render time. Tailwind classes
 * still apply to non-SVG slots; this is for the icon's `:color` prop.
 *
 * Resolution order: `appConfig.ui[semantic]`, then `appConfig.ui.gray` for
 * `neutral`, then the default palette mapping.
 */
export function resolveColorHex(
  appConfig: AppConfig,
  semantic: string | undefined,
  shade: number | string = 500,
): string {
  const name = semantic || 'primary'

  const ui = appConfig.ui as Record<string, unknown>
  let palette = typeof ui[name] === 'string' ? (ui[name] as string) : undefined
  if (!palette && name === 'neutral' && typeof ui.gray === 'string') palette = ui.gray as string
  if (!palette) palette = SEMANTIC_TO_PALETTE_DEFAULT[name] ?? 'slate'

  const scale = (twColors as unknown as Record<string, Record<string, string> | string>)[palette]
  // `black` / `white` are single strings in `tailwindcss/colors`, not 11-shade
  // scales, so every shade resolves to the one value. Without this a monochrome
  // accent silently fell back to slate-500 for baked SVG fills.
  if (typeof scale === 'string') return scale
  return scale?.[String(shade)] ?? FALLBACK_HEX
}

import { createTV as createTVOriginal } from 'tailwind-variants'

/**
 * Public alias for the `createTV` config arg: `tailwind-variants` 0.3.x declares
 * `TVConfig` internally but never re-exports it, so it is derived from the
 * function signature here.
 */
export type TVConfig = Parameters<typeof createTVOriginal>[0]

/**
 * Wrapper around `tailwind-variants`' `createTV` factory, with an optional
 * config so callers outside a `VyUI` app can call it with no args. The real
 * per-app `tv` factory is built inside `VyUI.install()`.
 */
export const createTv = (config: TVConfig = {}) => createTVOriginal(config)

/** Default singleton for components rendered outside an app context (storybook,
 *  tests). Mirrors `tailwind-variants`' own default `tv` export. */
export const tv = createTv()

import type { Component, InjectionKey } from 'vue'

/** Recursive `Partial<T>` — every nested property is also optional. */
export type DeepPartial<T> = {
  [K in keyof T]?: T[K] extends object ? DeepPartial<T[K]> : T[K]
}

/**
 * Per-component theme override bucket, keyed by component name. Each entry is a
 * partial of that component's resolved `tailwind-variants` config, typed loosely
 * here because component themes register lazily — strong typing happens at each
 * component boundary via `Partial<typeof theme>`.
 */
export type ComponentThemes = Record<string, unknown>

export interface AppConfig {
  ui: {
    /** Semantic primary color name (maps to a tailwind palette via CSS vars). */
    primary?: string
    /** Semantic gray/neutral color name. */
    gray?: string
    /** List of semantic color names exposed to component `color` variants. */
    colors?: string[]
    /** Semantic icon name → Iconify id (e.g. `loading` → `i-lucide-loader-circle`). */
    icons?: Record<string, string>
  } & ComponentThemes
}

export const APP_CONFIG_KEY: InjectionKey<AppConfig> = Symbol('vyui:app-config')

export interface VyUIPluginOptions {
  /** Override the default `ui` config — deep-merged over the package defaults. */
  ui?: DeepPartial<AppConfig['ui']>
  /** Register only this subset of components globally (keyed by tag name).
   *  Defaults to the full `REGISTRY`; an explicit set lets the bundler
   *  tree-shake the rest. */
  components?: Record<string, Component>
}

import type { App, Plugin } from 'vue'
import { defu } from 'defu'
import { APP_CONFIG_KEY, type AppConfig, type VyUIPluginOptions } from '@@vyui:lib/types'
import icons from '@@vyui:theme/icons'

const styleDefaults = {
  "primary": "blue"
}

/**
 * Package-level defaults; user options are deep-merged on top via `defu`.
 * Per-component theme overrides baked in here are picked up by each component
 * via `appConfig.ui[name]` → `tv({ extend: tv(base), ...overrides })`.
 */
const defaultConfig: AppConfig = {
  ui: { icons, gray: '__VYUI_GRAY__', ...styleDefaults },
}

/**
 * Vue plugin. Provides the merged `AppConfig` consumed by `useAppConfig`.
 * Register it once with your lib alias, e.g.
 * `createApp(App).use(VyUI, { ui: { primary: 'blue' } })`.
 */
export const VyUI: Plugin<VyUIPluginOptions> = {
  install(app: App, options: VyUIPluginOptions = {}) {
    const merged = defu({ ui: options.ui ?? {} }, defaultConfig) as AppConfig
    app.provide(APP_CONFIG_KEY, merged)
  },
}

/*
 * @vyui/kit — `liquid-glass` style tokens (overlay over the default style.css).
 *
 * iOS-flavoured "liquid glass": translucent surfaces, hairline separators,
 * Apple system accent colors, and a continuous-looking corner radius. A
 * TOKEN-ONLY overlay — it ships ONLY `style.css`, so the generated
 * `r/liquid-glass/` registry reuses every base `.vue` + `theme/*.ts` verbatim.
 *
 * ── WHAT "GLASS" MEANS HERE ────────────────────────────────────────────────
 * Lynx has NO `backdrop-filter` (its `filter` shorthand only blurs an element's
 * OWN content — see `@lynx-js/tailwind-preset`'s `blur-*`), so a true
 * frosted-backdrop material is not expressible on device. What this style does
 * instead is the other half of the material: surfaces and fills are translucent
 * `rgba()` so whatever sits behind them shows through, edges are hairline
 * separators rather than solid borders, and the radius scale is bumped. Over a
 * flat background it reads as "soft iOS"; over imagery / a scrolling list —
 * sheets, modals, sticky bars — it reads as glass.
 *
 * ── DELTAS FROM `default` ──────────────────────────────────────────────────
 *   • Accents: Apple system colors at the MODE tier (`--ui-primary` etc. hold
 *     the literal iOS blue/green/red/… rather than a Tailwind -500), with the
 *     closest Tailwind palette under each ramp so `bg-primary-100`-style
 *     utilities still resolve.
 *   • Surfaces: `--ui-bg*` are translucent — a white/dark glass base plus the
 *     iOS grey `systemFill` ladder (0.08 → 0.20 alpha) for the muted/elevated/
 *     accented fills, preserving the base file's fill hierarchy.
 *   • Borders: iOS `separator` alphas instead of solid slate.
 *   • `--ui-radius: 0.875rem` (14px) — iOS control/card corners.
 *   • Text + the neutral ramp stay on `slate` `theme()` literals so the
 *     install-time `baseColor` substitution (`__VYUI_GRAY__`) still applies.
 *
 * Alpha lives in the token VALUE, not in a `/alpha` class modifier: Tailwind
 * can't emit an alpha variant of a `var()`-backed semantic color, so
 * `bg-default/70` produces no CSS (see docs/styling-audit.md).
 *
 * Values are `theme()` literals or plain `rgba()` — never `var(--ui-color-*)`
 * refs, which collapse on device (Lynx resolves one level of var()). See the
 * token + SYNC CONTRACT banners in `packages/kit/src/style.css`.
 */
:root {
  /* primary */
  --ui-color-primary-50:  theme('colors.blue.50');
  --ui-color-primary-100: theme('colors.blue.100');
  --ui-color-primary-200: theme('colors.blue.200');
  --ui-color-primary-300: theme('colors.blue.300');
  --ui-color-primary-400: theme('colors.blue.400');
  --ui-color-primary-500: theme('colors.blue.500');
  --ui-color-primary-600: theme('colors.blue.600');
  --ui-color-primary-700: theme('colors.blue.700');
  --ui-color-primary-800: theme('colors.blue.800');
  --ui-color-primary-900: theme('colors.blue.900');
  --ui-color-primary-950: theme('colors.blue.950');

  /* secondary */
  --ui-color-secondary-50:  theme('colors.indigo.50');
  --ui-color-secondary-100: theme('colors.indigo.100');
  --ui-color-secondary-200: theme('colors.indigo.200');
  --ui-color-secondary-300: theme('colors.indigo.300');
  --ui-color-secondary-400: theme('colors.indigo.400');
  --ui-color-secondary-500: theme('colors.indigo.500');
  --ui-color-secondary-600: theme('colors.indigo.600');
  --ui-color-secondary-700: theme('colors.indigo.700');
  --ui-color-secondary-800: theme('colors.indigo.800');
  --ui-color-secondary-900: theme('colors.indigo.900');
  --ui-color-secondary-950: theme('colors.indigo.950');

  /* success */
  --ui-color-success-50:  theme('colors.green.50');
  --ui-color-success-100: theme('colors.green.100');
  --ui-color-success-200: theme('colors.green.200');
  --ui-color-success-300: theme('colors.green.300');
  --ui-color-success-400: theme('colors.green.400');
  --ui-color-success-500: theme('colors.green.500');
  --ui-color-success-600: theme('colors.green.600');
  --ui-color-success-700: theme('colors.green.700');
  --ui-color-success-800: theme('colors.green.800');
  --ui-color-success-900: theme('colors.green.900');
  --ui-color-success-950: theme('colors.green.950');

  /* info */
  --ui-color-info-50:  theme('colors.sky.50');
  --ui-color-info-100: theme('colors.sky.100');
  --ui-color-info-200: theme('colors.sky.200');
  --ui-color-info-300: theme('colors.sky.300');
  --ui-color-info-400: theme('colors.sky.400');
  --ui-color-info-500: theme('colors.sky.500');
  --ui-color-info-600: theme('colors.sky.600');
  --ui-color-info-700: theme('colors.sky.700');
  --ui-color-info-800: theme('colors.sky.800');
  --ui-color-info-900: theme('colors.sky.900');
  --ui-color-info-950: theme('colors.sky.950');

  /* warning */
  --ui-color-warning-50:  theme('colors.orange.50');
  --ui-color-warning-100: theme('colors.orange.100');
  --ui-color-warning-200: theme('colors.orange.200');
  --ui-color-warning-300: theme('colors.orange.300');
  --ui-color-warning-400: theme('colors.orange.400');
  --ui-color-warning-500: theme('colors.orange.500');
  --ui-color-warning-600: theme('colors.orange.600');
  --ui-color-warning-700: theme('colors.orange.700');
  --ui-color-warning-800: theme('colors.orange.800');
  --ui-color-warning-900: theme('colors.orange.900');
  --ui-color-warning-950: theme('colors.orange.950');

  /* error */
  --ui-color-error-50:  theme('colors.red.50');
  --ui-color-error-100: theme('colors.red.100');
  --ui-color-error-200: theme('colors.red.200');
  --ui-color-error-300: theme('colors.red.300');
  --ui-color-error-400: theme('colors.red.400');
  --ui-color-error-500: theme('colors.red.500');
  --ui-color-error-600: theme('colors.red.600');
  --ui-color-error-700: theme('colors.red.700');
  --ui-color-error-800: theme('colors.red.800');
  --ui-color-error-900: theme('colors.red.900');
  --ui-color-error-950: theme('colors.red.950');

  /* neutral — a FIXED slate scale (does not invert; see the DARK MODE banner) */
  --ui-color-neutral-50:  theme('colors.__VYUI_GRAY__.50');
  --ui-color-neutral-100: theme('colors.__VYUI_GRAY__.100');
  --ui-color-neutral-200: theme('colors.__VYUI_GRAY__.200');
  --ui-color-neutral-300: theme('colors.__VYUI_GRAY__.300');
  --ui-color-neutral-400: theme('colors.__VYUI_GRAY__.400');
  --ui-color-neutral-500: theme('colors.__VYUI_GRAY__.500');
  --ui-color-neutral-600: theme('colors.__VYUI_GRAY__.600');
  --ui-color-neutral-700: theme('colors.__VYUI_GRAY__.700');
  --ui-color-neutral-800: theme('colors.__VYUI_GRAY__.800');
  --ui-color-neutral-900: theme('colors.__VYUI_GRAY__.900');
  --ui-color-neutral-950: theme('colors.__VYUI_GRAY__.950');

  /*
   * Mode tier — picks the active shade for shorthand utilities (`bg-primary`).
   * Holds `theme()` LITERALS, not `var(--ui-color-*-500)` refs: `bg-primary`
   * resolves `var(--ui-primary)` (one hop) and Lynx native stops after one hop,
   * so a nested var() ref here would collapse on device. To rebrand the mode
   * tier, override these directly (overriding the `--ui-color-*` ramp no longer
   * flows through). The heavily-used ramp utilities (`bg-primary-500`) resolve
   * the ramp in one hop and still honor `--ui-color-*` overrides.
   *
   * `liquid-glass`: Apple's light-mode system colors, verbatim — no Tailwind
   * shade lands on them (systemBlue is more saturated than blue-500, systemRed
   * warmer than red-500), and a hex here is as single-hop as a `theme()` call.
   */
  --ui-primary:   #007aff; /* systemBlue */
  --ui-secondary: #5856d6; /* systemIndigo */
  --ui-success:   #34c759; /* systemGreen */
  --ui-info:      #5ac8fa; /* systemTeal */
  --ui-warning:   #ff9500; /* systemOrange */
  --ui-error:     #ff3b30; /* systemRed */

  /*
   * ── SEMANTIC TOKENS (mode-aware; flip in `.dark`) ──────────────────────────
   * Role-based aliases every theme + consumer uses INSTEAD of raw ramp classes,
   * so app chrome flips for free with zero `dark:`. `theme()` LITERALS only
   * (single-level var() rule) — redefined concretely in `.dark` below.
   */

  /* Text — foreground tiers, dim → strong. `text-default` = `var(--ui-text)`. */
  --ui-text-dimmed:      theme('colors.__VYUI_GRAY__.400');
  --ui-text-muted:       theme('colors.__VYUI_GRAY__.500');
  --ui-text-toned:       theme('colors.__VYUI_GRAY__.600');
  --ui-text:             theme('colors.__VYUI_GRAY__.700');
  --ui-text-highlighted: theme('colors.__VYUI_GRAY__.900');
  /* High-contrast foreground for `bg-inverted` fills (paired). */
  --ui-text-inverted:    theme('colors.white');

  /*
   * Background — THE GLASS. Same hierarchy as `default` (surface, then fills
   * light → strong), but every value is translucent so content behind a card /
   * sheet / bar shows through:
   *   • `bg-default` — the glass pane itself: mostly-opaque white, so text on
   *     it stays legible over an arbitrary backdrop (Lynx can't blur it — see
   *     the header). This is the one to keep high; dropping it much below 0.7
   *     starts to fail contrast over busy content.
   *   • `bg-muted` / `bg-elevated` / `bg-accented` — Apple's grey `systemFill`
   *     ladder. Neutral-grey rgb so a fill reads the same over a light or dark
   *     pane, alpha alone carrying the "stronger fill" step.
   */
  --ui-bg:          rgba(255, 255, 255, 0.72);
  --ui-bg-muted:    rgba(120, 120, 128, 0.08);
  --ui-bg-elevated: rgba(120, 120, 128, 0.12);
  --ui-bg-accented: rgba(120, 120, 128, 0.20);
  --ui-bg-inverted: rgba(28, 28, 30, 0.92);

  /* Border — iOS `separator` hairlines, not solid slate. */
  --ui-border:          rgba(60, 60, 67, 0.18);
  --ui-border-muted:    rgba(60, 60, 67, 0.10);
  --ui-border-accented: rgba(60, 60, 67, 0.29);
  --ui-border-inverted: rgba(28, 28, 30, 0.92);

  /*
   * Border-radius base — see the scale in `packages/kit/src/style.css`.
   * 0.875rem ≈ 14px, the iOS control/card corner. Bigger than every other
   * shipped style on purpose: rounded corners are most of what sells "iOS"
   * before any material effect does.
   */
  --ui-radius: 0.875rem;
}

/*
 * Dark tokens. See the DARK MODE banner. Only the mode tier + semantic tokens
 * are redefined; the neutral ramp stays FIXED (raw `neutral-*` classes do not
 * flip), and the accent ramps inherit `:root`. Values are literals — `theme()`
 * or `rgba()`, never a var() ref. Applied via a `.dark` class on an app-root
 * ancestor (`useColorMode`); custom-property inheritance flows to descendants.
 */
.dark {
  /* Mode tier — Apple's dark-mode system colors (their own brighter pairs). */
  --ui-primary:   #0a84ff;
  --ui-secondary: #5e5ce6;
  --ui-success:   #30d158;
  --ui-info:      #64d2ff;
  --ui-warning:   #ff9f0a;
  --ui-error:     #ff453a;

  /* Text — designed dark values (not a mechanical ramp flip). */
  --ui-text-dimmed:      theme('colors.__VYUI_GRAY__.500');
  --ui-text-muted:       theme('colors.__VYUI_GRAY__.400');
  --ui-text-toned:       theme('colors.__VYUI_GRAY__.300');
  --ui-text:             theme('colors.__VYUI_GRAY__.200');
  --ui-text-highlighted: theme('colors.white');
  --ui-text-inverted:    theme('colors.__VYUI_GRAY__.900');

  /*
   * Background — dark glass. The pane goes near-black-translucent; the grey
   * fill ladder keeps the same rgb as light mode and only lifts its alpha
   * (Apple's dark `systemFill` steps), so fills stay visible on it.
   */
  --ui-bg:          rgba(28, 28, 30, 0.72);
  --ui-bg-muted:    rgba(120, 120, 128, 0.16);
  --ui-bg-elevated: rgba(120, 120, 128, 0.24);
  --ui-bg-accented: rgba(120, 120, 128, 0.32);
  --ui-bg-inverted: rgba(255, 255, 255, 0.92);

  /* Border — the separator flips to a white hairline. */
  --ui-border:          rgba(255, 255, 255, 0.16);
  --ui-border-muted:    rgba(255, 255, 255, 0.08);
  --ui-border-accented: rgba(255, 255, 255, 0.28);
  --ui-border-inverted: rgba(255, 255, 255, 0.92);
}

/*
 * ── Modal (Dialog) open/close motion ───────────────────────────────────────
 * Inherited verbatim from the base style — see `packages/kit/src/style.css`
 * for the rationale (lifecycle classes, first-open flash, keyframe source).
 */
.vy-modal-overlay { opacity: 0; }
.vy-modal-overlay.ui-open { opacity: 1; }
.vy-modal-overlay.ui-entering { animation: vyui-fade-in 250ms ease-out both; }
.vy-modal-overlay.ui-leaving  { animation: vyui-fade-out 200ms ease-in both; }

.vy-modal-content { opacity: 0; }
.vy-modal-content.ui-open { opacity: 1; }
.vy-modal-content.ui-entering { animation: vyui-zoom-in 250ms ease-out both; }
